/* 길이 내림차순 — 긴 말이 먼저 잡혀야 한다 */
MAP.sort(function(a,b){ return b[0].length - a[0].length; });

G.cgoStyleKo2En = function(text){
  var src=String(text||''), left=src, hits=[], dropped=[], i;
  for(i=0;i<MAP.length;i++){
    var k=MAP[i][0], v=MAP[i][1];
    if(left.indexOf(k)>=0){
      left = left.split(k).join(' ');
      if(v){ if(hits.indexOf(v)<0) hits.push(v); }
      else   dropped.push(k);
    }
  }
  /* 남은 한국어는 Suno가 못 알아듣는다 — 보내지 않는다 */
  var rest = left.replace(/[가-힣]+/g,' ').replace(/\s+/g,' ').trim();
  var leftover = left.replace(/[^가-힣]+/g,' ').replace(/\s+/g,' ').trim();
  var en = hits.join(', ');
  if(rest) en = en ? (en+', '+rest) : rest;     // 영어·숫자는 그대로 둔다
  return { en: en, matched: hits, dropped: dropped,
           leftover: leftover ? leftover.split(' ').filter(Boolean) : [] };
};

