/* 선택한 성별·장르에 맞는 조합을 하나 뽑는다.
   cgo-491: genre 를 받는다. 이전에는 성별만 봐서, 트로트로 다 골라도
   '하드록 샤우팅'이 나왔고 그 영어 문구가 수노로 그대로 가서 곡이 록이 됐다.
   장르에 맞는 것이 없으면 null 을 돌려준다 — 아무거나 주는 것이 더 나쁘다. */
window.cgoVmixDraw = function(gender, genre){
  var pool = window.CGO_VMIX || [];
  var want = (gender==='female'?'f':gender==='male'?'m':gender==='duet'||gender==='choir'?'x':null);
  var p = want ? pool.filter(function(x){ return x.g===want; }) : pool;
  if(!p.length) p = pool;
  if(!p.length) return null;
  if(genre){
    var q = p.filter(function(x){ return window.cgoVmixCat491(x.cat)===genre; });
    if(!q.length) return null;
    p = q;
  }
  return p[Math.floor(Math.random()*p.length)];
};
window.CGO_DNA_V2_SUBS = {piano:'🎹 피아노 기반',power_rock:'⚡ 파워/록 발라드',rnb_soul:'🎷 알앤비/소울',acoustic_folk:'🪕 어쿠스틱/포크',orchestral_cinematic:'🎻 오케스트랄/시네마틱'};
