window.cgoDnaPool = function(mod){
  try{
    var v2 = window.CGO_DNA_V2 || [];
    var sub = mod && mod.selected && mod.selected.balladSub;
    if (v2.length && sub) {
      var p = v2.filter(function(x){ return x.sub === sub; });
      if (p.length >= 4) return { pool:p, tag:(window.CGO_DNA_V2_SUBS[sub]||sub), named:true };
    }
    var isPop = !!(mod && mod.selectedGenres && mod.selectedGenres.has && mod.selectedGenres.has('pop'));
    if (v2.length && isPop) return { pool:v2.slice(), tag:'팝·발라드 전체', named:true };
  }catch(e){}
  return { pool:(window.BALLAD_DNA_100||[]).slice(), tag:'전체', named:false };
};

